#include "ship_editor/ShipyardWorkspaceSystem.h"
#include <algorithm>
namespace subspace {std::vector<EditorAssetCard>ShipyardWorkspaceSystem::BuildAssetCards(const std::vector<ShipyardModuleRecord>&c){std::vector<EditorAssetCard>o;for(const auto&r:c){EditorAssetCard a;a.assetId=r.source.moduleId;a.displayName=ShipyardPartTaxonomySystem::DisplayName(r);a.category=ShipyardModuleSystem::ClassName(r.moduleClass);a.subtitle=std::string(ShipyardModuleSystem::SemanticName(r.semantic))+" • "+ShipyardModuleSystem::SizeName(r.size);a.previewKey="shipyard:"+r.source.moduleId;a.tags={ShipyardModuleSystem::ClassName(r.moduleClass),ShipyardModuleSystem::SemanticName(r.semantic),ShipyardModuleSystem::SizeName(r.size)};if(!r.generatorEligible)a.badge="PCG QUARANTINED";o.push_back(std::move(a));}return o;}std::vector<EditorOutlinerNode>ShipyardWorkspaceSystem::BuildOutliner(const std::vector<ShipyardModuleRecord>&c,const ProceduralShipVisualRecipe&r){std::vector<EditorOutlinerNode>o;o.push_back({"ship","","SHIP","Ship",true,false});for(std::size_t i=0;i<r.modules.size();++i){std::string l=r.modules[i].moduleId;for(const auto&x:c)if(x.source.moduleId==r.modules[i].moduleId){l=ShipyardPartTaxonomySystem::DisplayName(x);break;}std::string p="ship";for(const auto&a:r.attachments)if(a.childModuleIndex==i&&a.parentModuleIndex<r.modules.size()){p="module:"+std::to_string(a.parentModuleIndex);break;}o.push_back({"module:"+std::to_string(i),p,l,"ShipModule",true,false});}return o;}std::vector<EditorPropertySection>ShipyardWorkspaceSystem::BuildInspector(const ShipyardModuleRecord*r,const VisualModulePlacement*p,ShipyardWorkspaceMode m,bool adv){std::vector<EditorPropertySection>o;if(!r)return o;EditorPropertySection s{"summary","Summary",false,false,{}};s.properties.push_back({"name","Module",EditorPropertyType::ReadOnly,ShipyardPartTaxonomySystem::DisplayName(*r),{},"shipyard.module",true,false});s.properties.push_back({"semantic","Role",EditorPropertyType::ReadOnly,ShipyardModuleSystem::SemanticName(r->semantic),{},"shipyard.semantic",true,false});o.push_back(s);if(m==ShipyardWorkspaceMode::Build&&p){EditorPropertySection t{"transform","Transform",false,false,{}};t.properties.push_back({"position","Position",EditorPropertyType::Text,std::to_string(p->x)+", "+std::to_string(p->y)+", "+std::to_string(p->z),{},"shipyard.transform",true,false});o.push_back(t);}if(m==ShipyardWorkspaceMode::Model){EditorPropertySection a{"model","Model",false,false,{}};a.properties.push_back({"geometry","Geometry",EditorPropertyType::ReadOnly,"Add Shape / Stretch / Modifiers",{},"shipyard.model",true,false});o.push_back(a);}if(m==ShipyardWorkspaceMode::Interior){EditorPropertySection a{"interior","Interior",false,false,{}};a.properties.push_back({"interior","Interior",EditorPropertyType::ReadOnly,"Exterior module bindings / portals / walkable connections",{},"shipyard.interior",true,false});o.push_back(a);}if(m==ShipyardWorkspaceMode::Appearance){EditorPropertySection a{"appearance","Appearance",false,false,{}};a.properties.push_back({"paint","Paint Zones",EditorPropertyType::ReadOnly,"Primary / Secondary / Trim",{},"shipyard.appearance",true,false});o.push_back(a);}if(m==ShipyardWorkspaceMode::Systems){EditorPropertySection a{"systems","Systems",false,false,{}};a.properties.push_back({"functional","Functional",EditorPropertyType::Bool,r->functional?"true":"false",{},"shipyard.systems",false,false});o.push_back(a);}if(m==ShipyardWorkspaceMode::Character){EditorPropertySection a{"character","Character",false,false,{}};a.properties.push_back({"animation","Animation",EditorPropertyType::ReadOnly,"Humanoid scale / animation retarget / preview",{},"shipyard.character",true,false});o.push_back(a);}if(m==ShipyardWorkspaceMode::Pcg){EditorPropertySection a{"pcgstudio","PCG Studio",false,false,{}};a.properties.push_back({"pcg","PCG",EditorPropertyType::ReadOnly,"Generate / Reroll / Explain / Teach",{},"shipyard.pcgstudio",true,false});o.push_back(a);}if(m==ShipyardWorkspaceMode::World){EditorPropertySection a{"world","World",false,false,{}};a.properties.push_back({"terrain","Terrain",EditorPropertyType::ReadOnly,"Sculpt / Paint / Terraform",{},"shipyard.world",true,false});o.push_back(a);}if(m==ShipyardWorkspaceMode::DevWorld){EditorPropertySection a{"devworld","Dev World",false,false,{}};a.properties.push_back({"scene","Scene",EditorPropertyType::ReadOnly,"Scale reference / animation viewer / catalog / certified ships / PCG proving ground",{},"shipyard.devworld",true,false});o.push_back(a);}if(m==ShipyardWorkspaceMode::Authoring){EditorPropertySection a{"authoring","Advanced Authoring",false,false,{}};a.properties.push_back({"sockets","Sockets",EditorPropertyType::ReadOnly,std::to_string(r->sockets.size()),{},"shipyard.sockets",true,false});a.properties.push_back({"pcg","PCG Eligible",EditorPropertyType::Bool,r->generatorEligible?"true":"false",{},"shipyard.pcg",true,false});o.push_back(a);}if(adv){EditorPropertySection a{"advanced","Advanced",true,true,{}};a.properties.push_back({"assetId","Asset ID",EditorPropertyType::ReadOnly,r->source.moduleId,{},"shipyard.advanced",true,true});o.push_back(a);}return o;}EditorHelpRegistry ShipyardWorkspaceSystem::BuildHelpRegistry(){EditorHelpRegistry h;h.Register({"shipyard.module","Module","Reusable kitbash module.","Drag it from the parts browser into the viewport to preview placement before committing.","LMB / Drag"});h.Register({"shipyard.transform","Transform","Move, rotate, or scale the selected placed module.","Use direct manipulation in the viewport; numeric values are refinement controls.","W / E / R"});h.Register({"shipyard.sockets","Connections","Reusable mating points used for snapping and PCG.","Normal Build mode shows only relevant connection hints. Raw socket editing belongs to Authoring.",""});h.Register({"shipyard.pcg","Teach PCG","Correct how procedural generation understands this reusable part.","Changes are non-destructive authoring overrides over the certified source definition.",""});h.Register({"shipyard.appearance","Appearance","Paint, patterns, camouflage, decals, and faction livery.","Appearance works on semantic surface sections rather than raw material names.",""});h.Register({"shipyard.systems","Systems","Functional statistics and installation behavior.","Integrity, mass, power, heat, propulsion, weapons, shields, sensors, and cargo use this shared inspector.",""});h.Register({"shipyard.model","Model","Native geometry creation and non-destructive modification.","Add parametric shapes, stretch or transform them, then publish a reusable CanonicalAsset without leaving Subspace.",""});h.Register({"shipyard.pcgstudio","PCG Studio","Visual procedural-generation workbench.","Generate, reroll, inspect rejection reasons, toggle validation overlays, and teach PCG from good authored assemblies.",""});h.Register({"shipyard.world","World","Planet/world authoring and terraforming.","Sculpt terrain, paint semantic world layers, plan grading, and author deterministic terraform deltas against the live planetary world authority.",""});h.Register({"shipyard.interior","Interior","Exterior-to-interior module authoring.","Assign walkable rooms, corridors, service access, doors, hatches and airlocks so compatible exterior modules connect through certified interior portals.",""});h.Register({"shipyard.character","Character","Canonical player-scale and animation preview lane.","Calibrate humanoid scale, retarget governed animation libraries and preview movement against the same player reference used by doors, decks and world construction.",""});h.Register({"shipyard.devworld","Dev World","Large in-game proving ground for the entire authoring stack.","Lay out source kitbash assets, certified ships, interior kits, character scale references, PCG examples and world/lighting test zones on configurable development backdrops.",""});return h;}std::vector<ShipyardSurfaceSection>ShipyardWorkspaceSystem::DefaultSurfaceSections(const ShipyardModuleRecord&r){std::vector<ShipyardSurfaceSection>o;ShipyardSurfaceSection h;h.id="hull.primary";h.sourceMaterial="*";h.semantic="HullPrimary";h.primaryPaint=h.pattern=h.decal=h.factionLivery=true;o.push_back(h);if(r.semantic==ShipyardModuleSemantic::MainEngine||r.semantic==ShipyardModuleSemantic::EngineNozzle||r.semantic==ShipyardModuleSemantic::RcsThruster){ShipyardSurfaceSection n;n.id="propulsion.nozzle";n.semantic="Nozzle";n.trimPaint=n.emissiveOverride=true;o.push_back(n);}if(r.semantic==ShipyardModuleSemantic::CommandCockpit||r.semantic==ShipyardModuleSemantic::CommandBridge){ShipyardSurfaceSection g;g.id="command.glass";g.semantic="GlassCanopy";g.needsReview=true;o.push_back(g);}return o;}ShipyardModuleItemDefinition ShipyardWorkspaceSystem::BuildItemDefinition(const ShipyardModuleRecord&r){ShipyardModuleItemDefinition i;i.moduleId=r.source.moduleId;i.displayName=ShipyardPartTaxonomySystem::DisplayName(r);float v=std::max(.01f,(r.source.halfWidth*2)*(r.source.halfLength*2)*(r.source.halfHeight*2));i.mass=v*.9f;i.hitPoints=80+v*95+(r.primaryHull?180:0);i.powerDraw=r.functional?5:0;i.heat=r.semantic==ShipyardModuleSemantic::MainEngine?18:(r.functional?4:0);i.rarity=r.generatorEligible?0:2;i.manufacturer="Subspace Certified";i.iconKey="module:"+r.source.moduleId;return i;}}
